function [t] = dispersed_period(h)
%DISPERSED_PERIOD  The period of the circular orbit at a dispersed altitude h (a campaign's alt_km).
%   h: real[km] (passed in m)
%   returns t: real[s] (passed in s)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    t = 0;
    r = (6378137 + h);
    h__162 = ((r * r * r) / 398600441800000);
    if h__162 < 0, h__162 = NaN; else, h__162 = sqrt(h__162); end
    t = ((2 * pi) * h__162);
end
